contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");
        require(amount > 0, "amount must be positive");

        c.sendMoney(address(c), amount); if (__ESBMC_reverted()) return;

        uint balBeforeWithdraw = address(c).balance;

        bool withdrewReverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        uint balAfterWithdraw = address(c).balance;

        assert(
            (withdrewReverted && v > balBeforeWithdraw) ||
            (!withdrewReverted && balAfterWithdraw == balBeforeWithdraw - v)
        );
    }

    receive() external payable {}
}

