// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.sendMoney(address(c), amount) {} catch { return; }
        uint balBeforeWithdraw = address(c).balance;
        bool withdrewReverted;
        try c.withdraw(v) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint balAfterWithdraw = address(c).balance;
        assertTrue((withdrewReverted && v > balBeforeWithdraw) ||
            (!withdrewReverted && balAfterWithdraw == balBeforeWithdraw - v));
    }

    function testFuzz_run(uint256 v, uint256 amount) public {
        _run(v, amount);
    }

    receive() external payable {}
}
